import itertools

def calculate_autocorrelation_sum(seq):
    n = len(seq)
    sum_sq = 0
    for k in range(1, n):
        c_k = 0
        for i in range(n - k):
            c_k += seq[i] * seq[i+k]
        sum_sq += c_k**2
    return sum_sq

def find_sequence():
    # Using itertools.product to generate all 2^20 sequences
    # This might be slow, let's see if we can optimize or if it's fast enough.
    # 2^20 is ~1 million. 1 million * 20 * 20 operations is ~400 million.
    # This should run within a few seconds in Python.

    for seq in itertools.product([-1, 1], repeat=20):
        if calculate_autocorrelation_sum(seq) <= 49:
            return list(seq)
    return None

result = find_sequence()
print(result)
